import { Injectable, inject } from '@angular/core';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { tap } from 'rxjs';

export interface LoginResponse {
  accessToken: string;
  refreshToken: string;
  tokenType: string;
  expiresIn: number;
  user: {
    id: number;
    email: string;
    fullName: string;
    role: string;
    roles: string[];
    batchId: number | null;
    organizationId: number | null;
  };
}

/**
 * Handles admin/faculty portal authentication: login, token storage, logout,
 * and role checks. Faculty (INSTRUCTOR) and Admin are both allowed into the
 * portal, but their menu access differs (handled by the layout + guards).
 */
@Injectable({ providedIn: 'root' })
export class AuthService {
  private http = inject(HttpClient);
  private router = inject(Router);

  /** Same-origin API base URL (same logic as ApiService.getApiBaseUrl). */
  private get apiBaseUrl(): string {
    if (typeof window !== 'undefined' && (window as any).__env?.apiUrl) {
      return (window as any).__env.apiUrl;
    }
    if (typeof window !== 'undefined' && typeof window.location !== 'undefined') {
      const host = window.location.hostname;
      if (host !== 'localhost' && host !== '127.0.0.1') {
        return window.location.origin;
      }
    }
    return 'http://localhost:8080';
  }

  login(email: string, password: string) {
    return this.http.post<LoginResponse>(`${this.apiBaseUrl}/api/auth/login`, { email, password }).pipe(
      tap(response => {
        localStorage.setItem('access_token', response.accessToken);
        localStorage.setItem('refresh_token', response.refreshToken);
        localStorage.setItem('user', JSON.stringify(response.user));
      })
    );
  }

  get token(): string | null {
    return localStorage.getItem('access_token');
  }

  get user(): LoginResponse['user'] | null {
    const raw = localStorage.getItem('user');
    return raw ? JSON.parse(raw) : null;
  }

  get isAdmin(): boolean {
    const u = this.user;
    return !!u && (u.roles?.includes('ADMIN') || u.role === 'ADMIN');
  }

  /** Super Admin - ADMIN role. Only on localhost, access to Organizations. */
  get isSuperAdmin(): boolean {
    return this.isAdmin;
  }

  /** Organization Admin - INSTITUTE_ADMIN role. Can manage faculty, batches, courses within org */
  get isOrgAdmin(): boolean {
    const u = this.user;
    return !!u && (u.roles?.includes('INSTITUTE_ADMIN') || u.role === 'INSTITUTE_ADMIN');
  }

  /** Current user's role (ADMIN, INSTITUTE_ADMIN, INSTRUCTOR, STUDENT) */
  get userRole(): string | null {
    return this.user?.role ?? null;
  }

  /** Current user's organization ID if they belong to one */
  get organizationId(): number | null {
    return this.user?.organizationId ?? null;
  }


  /** Faculty role (INSTRUCTOR). Allowed in the portal but with restricted menus/data. */
  get isFaculty(): boolean {
    const u = this.user;
    return !!u && (u.roles?.includes('INSTRUCTOR') || u.role === 'INSTRUCTOR');
  }

  /** The batch this user (student/faculty) belongs to, if any. */
  get batchId(): number | null {
    return this.user?.batchId ?? null;
  }

  /** Allowed to access the portal (super admin, org admin, or faculty, logged in). */
  get isPortalUser(): boolean {
    return this.isAdmin || this.isOrgAdmin || this.isFaculty;
  }

  isLoggedIn(): boolean {
    return !!this.token && !!this.user;
  }

  logout() {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    localStorage.removeItem('user');
    this.router.navigate(['/login']);
  }
}
